1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.time.LocalDate;
13	import java.time.Period;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
24	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
25	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
28	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
29	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
30	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
31	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
32	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
33	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
34	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
35	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
36	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
37	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
38	    @Mapping(target = "bulkSignupWarning", ignore = true)
39	    @Mapping(target = "capacityWarning", ignore = true)
40	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
41	    OwnerDto toOwnerDto(Owner owner);
42	
43	    /**
44	     * Derives an owner's age band from the birth date, computed against the registration date
45	     * (falling back to the current date when the registration date is absent): {@code MINOR} when
46	     * under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older. Returns
47	     * {@code null} when no birth date is present, so the field is omitted from the response.
48	     */
49	    default OwnerDto.AgeBandEnum formatAgeBand(Owner owner) {
50	        if (owner == null || owner.getBirthDate() == null) {
51	            return null;
52	        }
53	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
54	        int age = Period.between(owner.getBirthDate(), asOf).getYears();
55	        if (age < 18) {
56	            return OwnerDto.AgeBandEnum.MINOR;
57	        }
58	        if (age < 65) {
59	            return OwnerDto.AgeBandEnum.ADULT;
60	        }
61	        return OwnerDto.AgeBandEnum.SENIOR;
62	    }
63	
64	    /**
65	     * Derives an owner's duplicate-detection identity key as the lower-case SHA-256 hex digest over
66	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} from the stored (already
67	     * E.164-normalized) telephone, lower-cased email and the Soundex code of the last name. A
68	     * {@code null} telephone or email contributes the empty string in its position.
69	     */
70	    default String formatIdentityKey(Owner owner) {
71	        if (owner == null) {
72	            return null;
73	        }
74	        return org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(
75	            owner.getTelephone(), owner.getEmail(), owner.getLastName());
76	    }
77	
78	    /**
79	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
80	     * (non-null and non-blank), otherwise {@code PHONE}.
81	     */
82	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
87	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
88	    }
89	
90	    /**
91	     * Derives an owner's locality (region) from the customer-code identity: it is the {@code REGION}
92	     * segment of the {@code '<REGION>-<HASH8>'} customer code (the part before the first {@code '-'}).
93	     * When the customer code is absent it falls back to resolving the region directly, preferring the
94	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and then the fixed city-to-region
95	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), yielding
96	     * {@code "UNKNOWN"} when neither resolves.
97	     */
98	    default String formatLocality(Owner owner) {
99	        if (owner == null) {
100	            return null;
101	        }
102	        String code = owner.getCustomerCode();
103	        if (code != null) {
104	            int dash = code.indexOf('-');
105	            if (dash > 0) {
106	                return code.substring(0, dash);
107	            }
108	        }
109	        String fromPostcode = regionForPostcode(owner.getPostcode());
110	        if (fromPostcode != null) {
111	            return fromPostcode;
112	        }
113	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
114	            case "Sydney" -> "NSW";
115	            case "Melbourne" -> "VIC";
116	            case "Brisbane" -> "QLD";
117	            default -> "UNKNOWN";
118	        };
119	    }
120	
121	    /**
122	     * Derives an owner's IANA timezone from the locality (region) via the fixed region-to-timezone
123	     * table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
124	     * {@code QLD -> Australia/Brisbane}. Returns {@code null} when the region is not one of these,
125	     * so the field is omitted from the response.
126	     */
127	    default String formatTimezone(Owner owner) {
128	        if (owner == null) {
129	            return null;
130	        }
131	        return switch (formatLocality(owner)) {
132	            case "NSW" -> "Australia/Sydney";
133	            case "VIC" -> "Australia/Melbourne";
134	            case "QLD" -> "Australia/Brisbane";
135	            default -> null;
136	        };
137	    }
138	
139	    /**
140	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
141	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
142	     * no known range, signalling that the caller should fall back to the city-to-region table.
143	     */
144	    private String regionForPostcode(String postcode) {
145	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
146	            return null;
147	        }
148	        int value = Integer.parseInt(postcode);
149	        if (value >= 2000 && value <= 2099) {
150	            return "NSW";
151	        }
152	        if (value >= 3000 && value <= 3099) {
153	            return "VIC";
154	        }
155	        if (value >= 4000 && value <= 4099) {
156	            return "QLD";
157	        }
158	        return null;
159	    }
160	
161	    /**
162	     * Computes an owner's membership points, starting at 0: plus 2 when an email is present, plus 1
163	     * when the owner's namesake count is 0, plus 2 for a household of 3 or more, plus 3 when the
164	     * owner's tenure exceeds 365 days.
165	     */
166	    default Integer formatMembershipPoints(Owner owner) {
167	        if (owner == null) {
168	            return null;
169	        }
170	        int points = 0;
171	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
172	        if (hasEmail) {
173	            points += 2;
174	        }
175	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
176	        if (unique) {
177	            points += 1;
178	        }
179	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
180	        if (largeHousehold) {
181	            points += 2;
182	        }
183	        boolean tenured = owner.getRegistrationDate() != null
184	            && fiscalYearStart(LocalDate.now()) - fiscalYearStart(owner.getRegistrationDate()) >= 1;
185	        if (tenured) {
186	            points += 3;
187	        }
188	        return points;
189	    }
190	
191	    /**
192	     * Derives an owner's membership level, a number from 1 to 4, from the owner's membership points:
193	     * 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
194	     */
195	    default Integer formatMembershipLevel(Owner owner) {
196	        if (owner == null) {
197	            return null;
198	        }
199	        int points = formatMembershipPoints(owner);
200	        if (points <= 1) {
201	            return 1;
202	        }
203	        if (points <= 3) {
204	            return 2;
205	        }
206	        if (points <= 5) {
207	            return 3;
208	        }
209	        return 4;
210	    }
211	
212	    /**
213	     * Computes an owner's check digit: a single Luhn check digit (0-9) over the digits contained in the
214	     * customer code. Returns {@code null} when the customer code is absent.
215	     */
216	    default Integer formatCheckDigit(Owner owner) {
217	        if (owner == null || owner.getCustomerCode() == null) {
218	            return null;
219	        }
220	        String code = owner.getCustomerCode();
221	        int sum = 0;
222	        boolean dbl = true;
223	        for (int i = code.length() - 1; i >= 0; i--) {
224	            char c = code.charAt(i);
225	            if (c < '0' || c > '9') {
226	                continue;
227	            }
228	            int d = c - '0';
229	            if (dbl) {
230	                d *= 2;
231	                if (d > 9) {
232	                    d -= 9;
233	                }
234	            }
235	            sum += d;
236	            dbl = !dbl;
237	        }
238	        return (10 - (sum % 10)) % 10;
239	    }
240	
241	    /**
242	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
243	     * digits of the fiscal year (starting 1 July) of the business-day-adjusted registration date
244	     * (e.g. {@code "NSW-1A2B3C4D-M26"}). Returns {@code null} when the customer code or registration
245	     * date is absent.
246	     */
247	    default String formatMembershipNumber(Owner owner) {
248	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
249	            return null;
250	        }
251	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYearStart(owner.getRegistrationDate()) % 100);
252	    }
253	
254	    /**
255	     * Formats an owner's fiscal year as {@code 'FY<YY>'}, where YY is the last two digits of the
256	     * starting calendar year of the fiscal year (starting 1 July) that contains the owner's
257	     * business-day-adjusted registration date (e.g. 5 August 2026 yields {@code "FY26"} and 3 March
258	     * 2026 yields {@code "FY25"}). Returns {@code null} when the registration date is absent.
259	     */
260	    default String formatFiscalYear(Owner owner) {
261	        if (owner == null || owner.getRegistrationDate() == null) {
262	            return null;
263	        }
264	        return String.format("FY%02d", fiscalYearStart(owner.getRegistrationDate()) % 100);
265	    }
266	
267	    /**
268	     * Returns the starting calendar year of the fiscal year (which starts on 1 July) that contains
269	     * the given date: the date's own year when it falls on or after 1 July, otherwise the previous
270	     * year.
271	     */
272	    private int fiscalYearStart(LocalDate date) {
273	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
274	    }
275	
276	    /**
277	     * Formats an owner's stored E.164 telephone for humans as the country code, a space, and the
278	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
279	     * The raw {@code telephone} value stays in E.164 form. Returns the stored value unchanged when it
280	     * is {@code null} or not a well-formed E.164 string (a {@code '+'} followed by digits).
281	     */
282	    default String formatTelephoneDisplay(Owner owner) {
283	        if (owner == null) {
284	            return null;
285	        }
286	        String telephone = owner.getTelephone();
287	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
288	            return telephone;
289	        }
290	        String digits = telephone.substring(1);
291	        int countryCodeLength = countryCodeLength(digits);
292	        String countryCode = digits.substring(0, countryCodeLength);
293	        String national = digits.substring(countryCodeLength);
294	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
295	        for (int i = 0; i < national.length(); i += 3) {
296	            grouped.append(' ').append(national, i, Math.min(i + 3, national.length()));
297	        }
298	        return grouped.toString();
299	    }
300	
301	    /**
302	     * Determines the length of the country-code segment of an E.164 number's digits (its digits
303	     * without the leading {@code '+'}): 1 for the NANP ({@code '+1'}) and 2 otherwise (e.g. Australia's
304	     * {@code '+61'}), mirroring the country codes the application normalises to.
305	     */
306	    private int countryCodeLength(String digits) {
307	        return digits.startsWith("1") ? 1 : 2;
308	    }
309	
310	    /**
311	     * Formats an owner's canonical self link as {@code "/api/owners/" + id} from the stored id.
312	     * Returns {@code null} when the owner or its id is absent, so the field is omitted from the
313	     * response.
314	     */
315	    default String formatSelfLink(Owner owner) {
316	        if (owner == null || owner.getId() == null) {
317	            return null;
318	        }
319	        return "/api/owners/" + owner.getId();
320	    }
321	
322	    /**
323	     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
324	     */
325	    default String formatDisplayName(Owner owner) {
326	        if (owner == null) {
327	            return null;
328	        }
329	        return owner.getLastName() + ", " + owner.getFirstName();
330	    }
331	
332	    /**
333	     * Formats an owner's salutation as the title and last name separated by a single space
334	     * (e.g. {@code "DR Franklin"}) when a title is present, or just the last name when no title
335	     * is given (null or blank). Returns {@code null} when the owner is {@code null}.
336	     */
337	    default String formatSalutation(Owner owner) {
338	        if (owner == null) {
339	            return null;
340	        }
341	        String title = owner.getTitle();
342	        if (title == null || title.isBlank()) {
343	            return owner.getLastName();
344	        }
345	        return title + " " + owner.getLastName();
346	    }
347	
348	    /**
349	     * Formats an owner's initials as the upper-cased first letters of the first and last
350	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
351	     */
352	    default String formatInitials(Owner owner) {
353	        if (owner == null) {
354	            return null;
355	        }
356	        return initial(owner.getFirstName()) + initial(owner.getLastName());
357	    }
358	
359	    private String initial(String name) {
360	        if (name == null || name.isEmpty()) {
361	            return "";
362	        }
363	        return Character.toUpperCase(name.charAt(0)) + ".";
364	    }
365	
366	    Owner toOwner(OwnerDto ownerDto);
367	
368	    @Mapping(target = "id", ignore = true)
369	    @Mapping(target = "pets", ignore = true)
370	    Owner toOwner(OwnerFieldsDto ownerDto);
371	
372	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
373	
374	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
375	
376	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
377	        OwnerPageDto ownerPageDto = new OwnerPageDto();
378	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
379	        ownerPageDto.setPage(ownerPage.getNumber());
380	        ownerPageDto.setSize(ownerPage.getSize());
381	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
382	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
383	        return ownerPageDto;
384	    }
385	}
